@KafkaListener(topics = "ledgerflow.ledger.wallet-hold.events.v1")
void onFundsHeld(EventEnvelope<FundsHeld> event, Acknowledgment ack) {
    notifier.send(event.payload());   // 1. do the work
    ack.acknowledge();                // 2. only then record that we did it
}

@RetryableTopic(
        attempts = "4",
        backoff = @Backoff(delay = 1000, multiplier = 3.0),   // 1s, 3s, 9s
        dltTopicSuffix = ".dlt.v1",
        exclude = { InvalidPayloadException.class })          // poison pills skip retry
@KafkaListener(topics = "ledgerflow.ledger.wallet-hold.events.v1")
void onFundsHeld(EventEnvelope<FundsHeld> event, Acknowledgment ack) { ... }

@DltHandler
void onDead(EventEnvelope<FundsHeld> event) {
    log.error("gave up on event {} for hold {}", event.eventId(), event.aggregateId());
}
